<script setup>import AuroraModal from './AuroraModal.vue';import AuroraButton from '../core/AuroraButton.vue';defineProps({open:Boolean,title:String,body:String,confirmLabel:{default:'Continuar'},cancelLabel:{default:'Volver'},pauseLabel:String,destructive:Boolean});defineEmits(['confirm','cancel','pause'])</script>
<template><AuroraModal :open="open" :title="title" :width="380" alert @close="$emit('cancel')"><p>{{body}}</p><template #footer><AuroraButton data-modal-initial-focus variant="ghost" @click="$emit('cancel')">{{cancelLabel}}</AuroraButton><AuroraButton v-if="pauseLabel" variant="secondary" @click="$emit('pause')">{{pauseLabel}}</AuroraButton><AuroraButton :variant="destructive?'danger':'primary'" @click="$emit('confirm')">{{confirmLabel}}</AuroraButton></template></AuroraModal></template>
<style scoped>p{margin:0;overflow-wrap:anywhere;color:var(--text-secondary);font:400 15px/1.55 var(--font-core)}</style>
